var b=WebApplication.CreateBuilder(args); b.Services.AddControllersWithViews(); b.Services.AddDistributedMemoryCache(); b.Services.AddSession(); b.Services.AddHttpContextAccessor(); b.Services.AddHttpClient<RaceDay.Web.ApiClient>(c=>c.BaseAddress=new Uri(b.Configuration["Api:BaseUrl"]!)); var app=b.Build(); app.UseStaticFiles();app.UseRouting();app.UseSession();app.MapControllerRoute("default","{controller=Home}/{action=Index}/{id?}");app.Run();
